default <- grDevices::palette()
print(default)
ns <- asNamespace("grDevices")
print(identical(getNamespace("grDevices"), ns))
print(identical(.Call(get("C_palette", ns), character()), default))
old <- withVisible(grDevices::palette(c("red", "#123456", "transparent")))
print(old)
print(grDevices::palette())
print(grDevices::col2rgb(1:3, alpha = TRUE))
print(withVisible(grDevices::palette("default")))
print(identical(grDevices::palette(), default))
print(withVisible(grDevices::palette("R3")))
print(grDevices::palette())
grDevices::palette(default)
for (value in list(1L, NA_character_, c("red", "no-such-colour"), rep("red", 1025))) {
    before <- grDevices::palette()
    print(tryCatch(.Call(get("C_palette", ns), value), error = function(e) conditionMessage(e)))
    print(identical(grDevices::palette(), before))
}
packed <- .Call(get("C_palette2", ns), integer())
print(packed)
print(identical(.Call(get("C_palette2", ns), packed[1:2]), packed))
print(grDevices::palette())
print(tryCatch(.Call(get("C_palette2", ns), c(1,2)), error = function(e) conditionMessage(e)))
.Call(get("C_palette2", ns), packed)
print(identical(grDevices::palette(), default))
file <- tempfile(fileext=".pdf")
grDevices::pdf(file)
print(withVisible(grDevices::palette(c("blue", "gold"))))
print(grDevices::palette())
grDevices::palette(default)
invisible(grDevices::dev.off())
unlink(file)
print(identical(grDevices::palette(), default))
